function App() {
  const [currentScreen, setCurrentScreen] = useState<string>('ChatChannels');
  const [screenProps, setScreenProps] = useState<Record<string, any>>({});

  const navigate = (screen: string, props?: Record<string, any>) => {
    if (props) setScreenProps(props);
    else setScreenProps({});
    setCurrentScreen(screen);
  };

  switch (currentScreen) {
    case 'ChatChannels':
      return <ChatChannels navigate={navigate} />;
    case 'ChannelThread':
      return <ChannelThread navigate={navigate} channelId={screenProps.channelId} />;
    case 'InstrumentDetail':
      return <InstrumentDetail navigate={navigate} symbol={screenProps.symbol} fromChannel={screenProps.fromChannel} />;
    case 'ShareToChat':
      return <ShareToChat navigate={navigate} symbol={screenProps.symbol} />;
    case 'CreateChannel':
      return <CreateChannel navigate={navigate} />;
    case 'JoinedChannels':
      return <JoinedChannels navigate={navigate} />;
    default:
      return <ChatChannels navigate={navigate} />;
  }
}

