function ChannelThread({ navigate, channelId }: { navigate: (screen: string, props?: Record<string, any>) => void; channelId?: string }) {
  const channel = CHANNELS.find(c => c.id === channelId) || CHANNELS[0];
  const [messages, setMessages] = useState(MESSAGES[channel.id] || []);
  const [inputText, setInputText] = useState('');
  const [tickerPrices, setTickerPrices] = useState<Record<string, { price: string; changePercent: number; lastUpdated: number }>>({
    'EMAAR': { price: 'AED 8.62', changePercent: 2.38, lastUpdated: Date.now() },
    'DAMAC': { price: 'AED 3.15', changePercent: 1.62, lastUpdated: Date.now() },
    'IDFM': { price: 'AED 24.80', changePercent: 0.95, lastUpdated: Date.now() },
  });
  const [priceFlash, setPriceFlash] = useState<Record<string, boolean>>({});

  // Simulate live ticker price updates every 15 seconds
  useEffect(() => {
    const interval = setInterval(() => {
      setTickerPrices(prev => {
        const updated: Record<string, { price: string; changePercent: number; lastUpdated: number }> = {};
        Object.keys(prev).forEach(sym => {
          const currentPrice = parseFloat(prev[sym].price.replace(/[^0-9.]/g, ''));
          const fluctuation = (Math.random() - 0.45) * 0.08;
          const newPrice = (currentPrice + fluctuation).toFixed(2);
          const currency = prev[sym].price.includes('AED') ? 'AED' : 'USD';
          const newChangePercent = parseFloat((prev[sym].changePercent + (fluctuation / currentPrice) * 100).toFixed(2));
          updated[sym] = { price: `${currency} ${newPrice}`, changePercent: newChangePercent, lastUpdated: Date.now() };
        });
        return updated;
      });
      setPriceFlash({ 'EMAAR': true, 'DAMAC': true, 'IDFM': true });
      setTimeout(() => setPriceFlash({}), 800);
    }, 15000);
    return () => clearInterval(interval);
  }, []);

  const handleSend = () => {
    if (!inputText.trim()) return;
    // Simulate moderation: messages containing "guaranteed" or "pump" are held
    const isFlagged = /guaranteed|pump|100% returns/i.test(inputText);
    const newMsg = {
      id: 'msg-' + Date.now(),
      userId: 'current-user',
      userName: 'You',
      avatar: '🧑',
      content: inputText,
      tickerCard: null,
      createdAt: 'Just now',
      moderationStatus: isFlagged ? 'pending' : 'approved',
    };
    setMessages([...messages, newMsg]);
    setInputText('');
  };

  return (
    <div className="min-h-screen bg-ui-background flex flex-col">
      {/* Header */}
      <div className="bg-ui-01 border-b border-divider-01 px-4 pt-12 pb-3">
        <div className="flex items-center gap-3">
          <button onClick={() => navigate('ChatChannels')} className="text-interactive font-primary text-label-semibold">
            ← Back
          </button>
          <div className="flex-1">
            <div className="flex items-center gap-2">
              <span>{channel.emoji}</span>
              <span className="font-primary text-p text-text-01">#{channel.name}</span>
            </div>
            <p className="font-body text-tiny text-text-03">{channel.memberCount} members · {channel.activeNow} online</p>
          </div>
        </div>
      </div>

      {/* Messages */}
      <div className="flex-1 overflow-y-auto px-4 py-4 space-y-4">
        {messages.map((msg) => (
          <div key={msg.id} className={`flex gap-3 ${msg.userId === 'current-user' ? 'flex-row-reverse' : ''}`}>
            <div className="w-8 h-8 rounded-full bg-ui-02 flex items-center justify-center text-sm flex-shrink-0">
              {msg.avatar}
            </div>
            <div className={`max-w-xs ${msg.userId === 'current-user' ? 'items-end' : ''}`}>
              <p className="font-primary text-tiny text-text-03 mb-1">
                {msg.userName} · {msg.createdAt}
              </p>
              {/* Moderation held state */}
              {msg.moderationStatus === 'pending' ? (
                <div className="rounded-md p-3 bg-yellow-light border border-yellow-dark">
                  <div className="flex items-center gap-2 mb-1">
                    <span className="text-xs">⏳</span>
                    <span className="font-primary text-tiny text-yellow-dark">Message under review</span>
                  </div>
                  <p className="font-body text-label text-text-02 opacity-60">
                    {msg.content}
                  </p>
                  <p className="font-body text-tiny text-yellow-dark mt-2">
                    Your message is being checked by our moderation system. It will appear to others once approved.
                  </p>
                </div>
              ) : (
                <div className={`rounded-md p-3 ${msg.userId === 'current-user' ? 'bg-interactive' : 'bg-ui-02'}`}>
                  <p className={`font-body text-label ${msg.userId === 'current-user' ? 'text-cta-01' : 'text-text-01'}`}>
                    {msg.content}
                  </p>
                </div>
              )}
              {msg.tickerCard && (
                <button
                  onClick={() => navigate('InstrumentDetail', { symbol: msg.tickerCard.symbol, fromChannel: channel.id })}
                  className="mt-2 w-full bg-ui-01 border border-ui-03 rounded-md p-3 shadow-card"
                >
                  <div className="flex items-center justify-between">
                    <div>
                      <p className="font-primary text-label-semibold text-text-01">{msg.tickerCard.symbol}</p>
                      <p className="font-body text-tiny text-text-03">{msg.tickerCard.name}</p>
                    </div>
                    <div className="text-right">
                      <p className={`font-primary text-label-semibold text-text-01 transition-all duration-300 ${priceFlash[msg.tickerCard.symbol] ? 'text-green scale-105' : ''}`}>
                        {tickerPrices[msg.tickerCard.symbol]?.price || msg.tickerCard.price}
                      </p>
                      <p className={`font-primary text-tiny ${(tickerPrices[msg.tickerCard.symbol]?.changePercent ?? msg.tickerCard.changePercent) >= 0 ? 'text-green' : 'text-red'}`}>
                        {(tickerPrices[msg.tickerCard.symbol]?.changePercent ?? msg.tickerCard.changePercent) >= 0 ? '+' : ''}{(tickerPrices[msg.tickerCard.symbol]?.changePercent ?? msg.tickerCard.changePercent).toFixed(2)}%
                      </p>
                    </div>
                  </div>
                  <div className="flex items-center gap-1 mt-2 pt-2 border-t border-divider-01">
                    <span className="inline-block w-2 h-2 rounded-full bg-green animate-pulse"></span>
                    <span className="font-body text-tiny text-text-04">Live · updates every 15s</span>
                  </div>
                </button>
              )}
            </div>
          </div>
        ))}
      </div>

      {/* Moderation hint */}
      <div className="px-4 pb-1">
        <p className="font-body text-tiny text-text-04 text-center">Messages are moderated for community safety</p>
      </div>

      {/* Compose */}
      <div className="bg-ui-01 border-t border-divider-01 px-4 py-3">
        <div className="flex items-center gap-2">
          <button
            onClick={() => navigate('ShareToChat', { symbol: 'EMAAR' })}
            className="w-10 h-10 rounded-full bg-ui-02 flex items-center justify-center flex-shrink-0"
          >
            <span className="text-interactive text-sm font-bold">$</span>
          </button>
          <input
            type="text"
            value={inputText}
            onChange={(e) => setInputText(e.target.value)}
            onKeyDown={(e) => e.key === 'Enter' && handleSend()}
            placeholder="Type a message..."
            className="flex-1 bg-ui-02 rounded-md px-4 py-3 text-label font-body text-text-01 placeholder-placeholder outline-none"
          />
          <button
            onClick={handleSend}
            className="w-10 h-10 rounded-full bg-interactive flex items-center justify-center flex-shrink-0"
          >
            <span className="text-cta-01 text-sm">↑</span>
          </button>
        </div>
      </div>
    </div>
  );
}

