function JoinedChannels({ navigate }: { navigate: (screen: string, props?: Record<string, any>) => void }) {
  const [joinedIds, setJoinedIds] = useState<string[]>(CHANNELS.filter(c => c.joined).map(c => c.id));
  const [showLeaveConfirm, setShowLeaveConfirm] = useState<string | null>(null);

  const joinedChannels = CHANNELS.filter(c => joinedIds.includes(c.id));

  const handleLeave = (channelId: string) => {
    setJoinedIds(prev => prev.filter(id => id !== channelId));
    setShowLeaveConfirm(null);
  };

  return (
    <div className="min-h-screen bg-ui-background">
      {/* Header */}
      <div className="bg-ui-01 border-b border-divider-01 px-4 pt-12 pb-4">
        <div className="flex items-center gap-3">
          <button onClick={() => navigate('ChatChannels')} className="text-interactive font-primary text-label-semibold">
            ← Back
          </button>
          <h1 className="font-primary text-p text-text-01 flex-1 text-center">My Channels</h1>
          <div className="w-16" />
        </div>
      </div>

      <div className="px-4 py-4">
        {joinedChannels.length === 0 ? (
          <div className="text-center py-12">
            <p className="font-body text-label text-text-03">You haven't joined any channels yet</p>
            <button
              onClick={() => navigate('ChatChannels')}
              className="mt-4 bg-interactive rounded-md px-6 py-3"
            >
              <span className="font-primary text-label-semibold text-cta-01">Browse Channels</span>
            </button>
          </div>
        ) : (
          <div className="space-y-3">
            <p className="font-body text-tiny text-text-03 mb-2">Swipe or tap the leave button to unsubscribe from a channel</p>
            {joinedChannels.map((channel) => (
              <div key={channel.id} className="bg-ui-01 rounded-md shadow-card p-4">
                <div className="flex items-center gap-3">
                  <button
                    onClick={() => navigate('ChannelThread', { channelId: channel.id })}
                    className="flex items-center gap-3 flex-1 text-left"
                  >
                    <span className="text-lg">{channel.emoji}</span>
                    <div className="flex-1">
                      <p className="font-primary text-label-semibold text-text-01">#{channel.name}</p>
                      <p className="font-body text-tiny text-text-03">{channel.topic}</p>
                    </div>
                  </button>
                  {channel.unreadCount > 0 && (
                    <span className="w-6 h-6 rounded-full bg-interactive flex items-center justify-center mr-2">
                      <span className="font-primary text-tiny text-cta-01">{channel.unreadCount}</span>
                    </span>
                  )}
                  <button
                    onClick={() => setShowLeaveConfirm(channel.id)}
                    className="px-3 py-2 rounded-sm bg-ui-error-01 border border-red-light"
                  >
                    <span className="font-primary text-tiny text-red">Leave</span>
                  </button>
                </div>
              </div>
            ))}
          </div>
        )}
      </div>

      {/* Leave Confirmation Modal */}
      {showLeaveConfirm && (
        <div className="fixed inset-0 bg-overlay-01 bg-opacity-50 flex items-end justify-center z-50">
          <div className="bg-ui-01 rounded-t-lg w-full max-w-md p-6 pb-10">
            <div className="w-10 h-1 bg-ui-03 rounded-full mx-auto mb-6"></div>
            <h3 className="font-primary text-p text-text-01 text-center mb-2">Leave Channel?</h3>
            <p className="font-body text-label text-text-03 text-center mb-6">
              You will no longer receive messages from #{CHANNELS.find(c => c.id === showLeaveConfirm)?.name}. You can rejoin anytime.
            </p>
            <div className="flex gap-3">
              <button
                onClick={() => setShowLeaveConfirm(null)}
                className="flex-1 rounded-md py-4 bg-ui-02"
              >
                <span className="font-primary text-label-semibold text-text-01">Cancel</span>
              </button>
              <button
                onClick={() => handleLeave(showLeaveConfirm)}
                className="flex-1 rounded-md py-4 bg-red"
              >
                <span className="font-primary text-label-semibold text-cta-01">Leave Channel</span>
              </button>
            </div>
          </div>
        </div>
      )}

      <BottomNav active="chat" navigate={navigate} />
    </div>
  );
}

